/**
 * Gather at Tabor
 * ---------------
 * The tribes rally on Tabor while Sisera marshals nine hundred iron chariots from Harosheth. Stage: a high hilltop mustering ground, spears glinting, campfires on the plain below; the enemy's chariot tracks darkening the valley; dawn assembly, mist on the heights.
 *
 * Palette 0xd8b878 → 0x9c8456 · light: dawn · hero: chariot
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./deborah-kit.js.
 */

import { THREE, createScene, cityGate, house, chariot, person, crowd, birds } from './deborah-kit.js';

const BG = 0xd8b878;
const GROUND = 0x776542;

export function build(group) {
    const W = createScene(group, { seed: 1566744798, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — dawn */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-58, 30, -145], 9, 0xffd9a0);
    W.disc([-58, 30, -155], 16, 0xffb060, 0.22);
    W.stars(60, 150, [0xcfd8e8, 0xbfd0e0], 0.55);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-60, 34, -120, 24], [10, 40, -135, 30], [70, 33, -125, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xd8c8b8, { opacity: 0.5 }), [x, y, z], { s: [s, s * 0.24, s * 0.5] });
    });
    W.backdrop(clouds);

    /* ground */
    W.ground(260, 260, 0, 0, 0x776542, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* hills: angular ridges on the horizon */
    const hills = W.grp(group, [0, 0, 0], { name: 'hills' });
    for (let i = 0; i < 9; i++) {
        const x = -130 + i * 32 + W.rr(-8, 8);
        W.add(hills, W.G('cone', W.rr(14, 28), W.rr(10, 24), 5), W.mat(0x594c32), [x, 0, -95 - W.rr(0, 25)], { r: [0, W.r() * 3, 0] });
    }
    W.backdrop(hills);

    /* city: gate, towers and houses on the far side */
    const city = W.grp(group, [-8, 0, -58], { name: 'city', r: [0, 0.13, 0] });
    cityGate(W, city, 0, 0, 0, 1.15, { stone: 0xa48b5a, trim: 0x5f5135 });
    for (let i = 0; i < 5; i++) {
        house(W, city, -34 + i * 17 + W.rr(-4, 4), 0, W.rr(-14, 6), 0.85 + W.r() * 0.4, { mud: 0x947d52 });
    }
    W.backdrop(city);

    /* chariot: gold-trimmed cab and spoked wheels */
    chariot(W, group, -6.0, 0, 4.2, 1.1, { ry: 0.23, gold: 0x826e48 });

    /* hero: the chariot */
    chariot(W, group, 0, 0, 0, 1.25, { ry: 0.3, gold: 0x826e48 });

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0xd8b878, ry: -0.07, s: 1.09 });
    person(W, group, [4.5, 0, 6], { robe: 0x9c8456, ry: -0.08, s: 1.00 });
    /* crowd: the people of the story */
    crowd(W, group, 0, 16, 15, 70, 44, [0xd8b878, 0x9c8456, 0x776542, 0x8a6a44, 0x6a4a30, 0xc8b088]);

    /* birds: slow circles high above */
    birds(W, group, 7, 55, { y: 26 });

    return W.finish();
}

export default { build };
